// Healing is non-destructive — it resets values, never erases history
export interface HealingResult {
  readonly spritesStabilized: number;
  readonly nucleusReset:      boolean;
  readonly archiveEntry:      string;
}

export function canHeal(status: string): boolean {
  return status !== "finished";
}

