pub struct HealingResult {
    pub sprites_stabilized: usize,
    pub nucleus_reset:      bool,
    pub archive_entry:      String,
}

/// CanHeal — toujours vrai sauf si le module est terminé
pub fn can_heal(status: &str) -> bool {
    status != "finished"
}
